function dedupeHits(hits: GraphHit[]) {
  const seen = new Set<string>();
  return hits.filter((h) => (seen.has(`${h.file}:${h.line}`) ? false : (seen.add(`${h.file}:${h.line}`), true))).slice(0, 8);
}

